CREATE TABLE route_definitions (id varchar(36) PRIMARY KEY,protocol varchar(16) NOT NULL,method varchar(16) NOT NULL,path varchar(512) NOT NULL,operation text NOT NULL,description text NOT NULL,service_name varchar(128) NOT NULL,source_version varchar(128) NOT NULL,status varchar(16) NOT NULL,last_discovered_at timestamp(6) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text NULL,UNIQUE KEY route_definitions_identity_unique(service_name,protocol,method,path),INDEX route_definitions_status_idx(service_name,status,protocol));
CREATE TABLE route_policy_definitions (id varchar(36) PRIMARY KEY,route_id varchar(36) NOT NULL,expression text NOT NULL,description text NOT NULL,status varchar(16) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text NULL,UNIQUE KEY route_policy_definitions_route_unique(route_id));
CREATE TABLE route_policy_permission_refs (id varchar(36) PRIMARY KEY,policy_id varchar(36) NOT NULL,permission_key varchar(128) NOT NULL,resource varchar(128) NOT NULL,action varchar(128) NOT NULL,scope varchar(16) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text NULL,UNIQUE KEY route_policy_permission_refs_key_unique(policy_id,permission_key),INDEX route_policy_permission_refs_policy_idx(policy_id));
CREATE TRIGGER route_definitions_audit_bi BEFORE INSERT ON route_definitions FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_at=NULL,NEW.deleted_by=NULL;
CREATE TRIGGER route_definitions_audit_bu BEFORE UPDATE ON route_definitions FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER route_definitions_audit_bd BEFORE DELETE ON route_definitions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
CREATE TRIGGER route_policy_definitions_audit_bi BEFORE INSERT ON route_policy_definitions FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_at=NULL,NEW.deleted_by=NULL;
CREATE TRIGGER route_policy_definitions_audit_bu BEFORE UPDATE ON route_policy_definitions FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER route_policy_definitions_audit_bd BEFORE DELETE ON route_policy_definitions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
CREATE TRIGGER route_policy_permission_refs_audit_bi BEFORE INSERT ON route_policy_permission_refs FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_at=NULL,NEW.deleted_by=NULL;
CREATE TRIGGER route_policy_permission_refs_audit_bu BEFORE UPDATE ON route_policy_permission_refs FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER route_policy_permission_refs_audit_bd BEFORE DELETE ON route_policy_permission_refs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
SET @app_actor_id='application-service:migration';
